def check_array_types(arr):
  """Checks the data types of all elements in a 2D array.

  Args:
    arr: A 2D list (list of lists).

  Returns:
    A dictionary where keys are the unique data types found and values are the number of times each type appears.
    Returns an empty dictionary if the input is not a valid 2D array or is empty.
  """
  if not isinstance(arr, list) or not all(isinstance(row, list) for row in arr):
    return {}

  if not arr:
    return {}

  type_counts = {}
  for row in arr:
    for element in row:
      element_type = type(element)
      if element_type in type_counts:
        type_counts[element_type] += 1
      else:
        type_counts[element_type] = 1
  return type_counts
```

