import os

def delete_empty_folder(path):
    """Deletes a folder if it is empty.

    Args:
        path (str): The path to the folder.
    """
    try:
        if not os.listdir(path):
            os.rmdir(path)
            print(f"Folder '{path}' deleted successfully.")
        else:
            print(f"Folder '{path}' is not empty, cannot delete.")
    except OSError as e:
        print(f"Error deleting folder '{path}': {e}")
