import os

def get_terminal_width():
    """Gets the character width of the terminal window."""
    try:
        # Use shutil.get_terminal_size() if available (Python 3.3+) 
        import shutil
        columns, rows = shutil.get_terminal_size()
        return columns
    except ImportError:
        # Fallback for older Python versions using os.get_env
        try:
            width = int(os.environ['COLUMNS'])  # Check COLUMNS environment variable
            return width
        except (KeyError, ValueError):
            # If COLUMNS is not set or invalid, try to determine it by querying the terminal.
            import subprocess
            try:
                result = subprocess.check_output(['tput', 'cols']).decode('utf-8').strip()
                return int(result)
            except (subprocess.CalledProcessError, OSError):
                # If all else fails, return a default value.
                return 80  # Default terminal width

if __name__ == '__main__':
    width = get_terminal_width()
    print(f"Terminal width: {width}")
```

